#ifndef __DOLFIN_FORM_H
#define __DOLFIN_FORM_H

#include <dolfin/fem/Coefficient.h>
#include <dolfin/fem/DofMapSet.h>
#include <dolfin/fem/FiniteElementSpace.h>
#include <dolfin/ufc/ufc.h>

#include <string>
#include <vector>

namespace dolfin
{

class CoefficientMap;
class SubSystem;
class GenericTensor;

/// Base class for UFC code generated by FFC for DOLFIN with option -l

class Form
{

public:
  using Coefficients = CoefficientMap;

  /// Constructor
  Form( Mesh & mesh );

  /// Destructor
  ~Form() = default;

  /// Return UFC form
  virtual auto form() const -> ufc::form const & = 0;

  /// Return array of coefficients
  virtual auto coefficients() const -> std::vector< Coefficient * > const & = 0;

  /// Return name of argument associated with the given number
  virtual auto coefficient_name( size_t i ) const -> std::string = 0;

  /// Return index of argument associated with the given name
  auto coefficient_index( std::string const & name ) const -> size_t;

  /// Update degree of freedom maps if needed
  void update_dofmaps() const;

  auto operator()() const -> ufc::form const & { return this->form(); }

  /// Return mesh
  auto mesh() const -> Mesh &;

  /// Return DofMapSet
  auto dofmaps() const -> DofMapSet &;

  //--- EXTENSION OF INTERFACE ------------------------------------------------

  /// Create function space for i-th function (arguments + coefficients)
  auto create_space( size_t i ) const -> FiniteElementSpace *;

  /// Create function space for given coefficient
  auto create_coefficient_space( std::string const & name ) const
    -> FiniteElementSpace *;

  /// Check dimension and rank of coefficients
  auto check( std::vector< Coefficient * > const & coefficients ) const -> bool;

  /// Check if index is valid
  auto is_valid_index( size_t i ) const -> bool;

  /// Assemble form
  void assemble( GenericTensor & T, bool reset_tensor );

protected:

  /// Assign coefficients from map to form coefficients
  void init( std::vector< Coefficient * > & coefficients );

  /// Assign coefficients from map to form coefficients
  void init( std::vector< Coefficient * > & coefficients,
             CoefficientMap &               map );

private:
  // Mesh
  Mesh & mesh_;

  // Degree of freedom maps
  mutable DofMapSet dof_map_set_;
};

//--- INLINES -----------------------------------------------------------------

inline void Form::update_dofmaps() const
{
  if ( dof_map_set_.size() == 0 )
  {
    dof_map_set_.update( *this, mesh_ );
  }
}

//-----------------------------------------------------------------------------

inline auto Form::mesh() const -> Mesh &
{
  return mesh_;
}

//-----------------------------------------------------------------------------

inline auto Form::dofmaps() const -> DofMapSet &
{
  this->update_dofmaps();
  return dof_map_set_;
}

//-----------------------------------------------------------------------------

inline auto Form::coefficient_index( std::string const & name ) const -> size_t
{
  for ( size_t i = 0; i < this->form().num_coefficients(); ++i )
  {
    if ( this->coefficient_name( i ) == name )
    {
      return i;
    }
  }
  error( "Form : coefficient name was not found" );
  return 0;
}

//----------------------------------------------------------------------------

inline auto Form::create_space( size_t i ) const -> FiniteElementSpace *
{
  ufc::finite_element * test_f = this->form().create_finite_element( i );
  ufc::dofmap *         test_d = this->form().create_dofmap( i );
  // For an argument the mesh is the one passed to the form and for coefficient
  // the mesh passed to the function.
  return new FiniteElementSpace( dofmaps()[i].mesh(), test_f, *test_d, true );
}

//----------------------------------------------------------------------------

inline auto Form::create_coefficient_space( std::string const & name ) const
  -> FiniteElementSpace *
{
  return this->create_space( this->form().rank() + this->coefficient_index( name ) );
}

//-----------------------------------------------------------------------------

} /* namespace dolfin */

#endif /* __DOLFIN_FORM_H */
